/**
 * @name Unsafe YAML deserialization with user input flow
 * @description User input flowing into yaml.load() without SafeLoader can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-yaml-deserialization
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module YamlDeserializationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("yaml").getMember(["load", "unsafe_load"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module YamlDeserializationFlow = TaintTracking::Global<YamlDeserializationConfig>;
import YamlDeserializationFlow::PathGraph

from YamlDeserializationFlow::PathNode source, YamlDeserializationFlow::PathNode sink
where YamlDeserializationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe YAML deserialization from $@.", source.getNode(), "user input"

/**
 * @name Path traversal vulnerability
 * @description User input flowing into file paths can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

